CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE organizations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, slug text UNIQUE NOT NULL, description text, location text, phone text, timezone text NOT NULL DEFAULT 'America/Santiago', deposit_percent integer NOT NULL DEFAULT 50 CHECK(deposit_percent BETWEEN 1 AND 100), marketplace_enabled boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, email text NOT NULL, name text NOT NULL, password_hash text NOT NULL, role text NOT NULL CHECK(role IN ('owner','manager','reception','operations','accounting')), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,email));
CREATE TABLE cabins (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, name text NOT NULL, slug text NOT NULL, type text NOT NULL DEFAULT 'cabin', description text, capacity integer NOT NULL CHECK(capacity>0), bedrooms integer NOT NULL DEFAULT 1, beds integer NOT NULL DEFAULT 1, bathrooms numeric(3,1) NOT NULL DEFAULT 1, nightly_rate integer NOT NULL CHECK(nightly_rate>=0), status text NOT NULL DEFAULT 'active', amenities jsonb NOT NULL DEFAULT '[]', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,slug));
CREATE TABLE cabin_photos (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, cabin_id uuid NOT NULL REFERENCES cabins(id) ON DELETE CASCADE, storage_key text NOT NULL, public_url text NOT NULL, category text NOT NULL DEFAULT 'other', sort_order integer NOT NULL DEFAULT 0, is_cover boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE guests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, full_name text NOT NULL, phone text, email text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE reservations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), cabin_id uuid NOT NULL REFERENCES cabins(id), guest_id uuid NOT NULL REFERENCES guests(id), check_in date NOT NULL, check_out date NOT NULL, adults integer NOT NULL DEFAULT 1, children integer NOT NULL DEFAULT 0, source text NOT NULL CHECK(source IN ('direct_web','hospeda_marketplace','airbnb','booking','whatsapp','manual')), status text NOT NULL, gross_amount integer NOT NULL CHECK(gross_amount>=0), deposit_percent integer NOT NULL CHECK(deposit_percent BETWEEN 1 AND 100), required_to_confirm integer NOT NULL CHECK(required_to_confirm>=0), marketplace_commission_rate numeric(5,4) NOT NULL DEFAULT 0, marketplace_commission_amount integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), CHECK(check_out>check_in));
CREATE TABLE payments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), reservation_id uuid NOT NULL REFERENCES reservations(id) ON DELETE CASCADE, provider text NOT NULL, provider_payment_id text, amount integer NOT NULL CHECK(amount>0), payment_kind text NOT NULL CHECK(payment_kind IN ('deposit','balance','full','refund')), status text NOT NULL CHECK(status IN ('pending','approved','rejected','refunded','cancelled')), method text, paid_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE operations_tasks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), cabin_id uuid NOT NULL REFERENCES cabins(id), reservation_id uuid REFERENCES reservations(id), type text NOT NULL CHECK(type IN ('cleaning','maintenance','inspection')), status text NOT NULL DEFAULT 'pending', assigned_to uuid REFERENCES users(id), due_at timestamptz NOT NULL, completed_at timestamptz);
CREATE INDEX reservations_calendar ON reservations(organization_id,cabin_id,check_in,check_out);CREATE INDEX payments_reservation ON payments(organization_id,reservation_id,status);CREATE INDEX cabin_photo_order ON cabin_photos(cabin_id,sort_order);CREATE INDEX operation_queue ON operations_tasks(organization_id,status,due_at);
